using System.Drawing;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    // .NET 9 breaking change: StatusStrip now defaults to ToolStripSystemRenderer instead of
    // ToolStripProfessionalRenderer. Explicitly set the renderer to preserve .NET 8 appearance.
    public StatusStrip CreateStatusStrip()
    {
        var statusStrip = new StatusStrip();
        statusStrip.RenderMode = ToolStripRenderMode.Professional;
        return statusStrip;
    }

    // .NET 9 breaking change: IWindowsFormsEditorService.DropDownControl no longer accepts null.
    // Guard against null before calling.
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }
}

